import java.util.Scanner;

public class Main {
    static int Mod;
    static int n, k;
    static long[] factorial;
    static long[] invFactorial;
    static long[] inverse;
    static long[][] f;

    static long fast_pow(int base, int exp) {
        long result = 1;
        long cur = base;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * cur) % Mod;
            cur = (cur * cur) % Mod;
            exp >>= 1;
        }
        return result;
    }

    static long compute(int used, int S) {
        if (f[used][S] != -1) return f[used][S];
        long answer = 0;
        if (S == 0) {
            answer = factorial[n];
            for (int i = 1; i <= used; ++i)
                answer = (answer * (k - i + 1)) % Mod;
            return f[used][S] = answer;
        }
        if (used > k) return 0;
        int lowest_bit = S & (-S);
        int remaining = S - lowest_bit;
        for (int T = remaining; ; T = (T - 1) & remaining) {
            answer = (answer + invFactorial[S - T] * compute(used + 1, T) % Mod) % Mod;
            if (T == 0) break;
        }
        return f[used][S] = answer;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        k = sc.nextInt();
        Mod = sc.nextInt();

        if (n % 2 == 1) {
            System.out.println(fast_pow(k, n));
            sc.close();
            return;
        }

        factorial = new long[n + 1];
        invFactorial = new long[n + 1];
        inverse = new long[n + 1];
        f = new long[19][n + 1];

        factorial[0] = 1;
        invFactorial[0] = 1;
        factorial[1] = 1;
        invFactorial[1] = 1;

        for (int i = 2; i <= n; ++i) {
            factorial[i] = (factorial[i - 1] * i) % Mod;
            inverse[i] = (long)((Mod - Mod / i) * invFactorial[(int)(Mod % i)] % Mod);
            invFactorial[i] = (invFactorial[i - 1] * inverse[i]) % Mod;
        }

        for (int i = 0; i <= 18; ++i)
            for (int j = 0; j <= n; ++j)
                f[i][j] = -1;

        long result = (fast_pow(k, n) - compute(0, n) + Mod) % Mod;
        System.out.println(result);
        sc.close();
    }
}
